def solve_small():
    from itertools import product

    maxA = 4
    results = {}

    def get_moves(state):
        # state is a tuple of (a_i, opened) for i=0..N-1
        moves = []
        N = len(state)
        for i in range(N):
            if state[i][0] == 0:
                continue
            new_state = list(state)
            a, op = new_state[i]
            new_a = a - 1
            new_op = op
            if op == 0:
                new_op = 1
            new_state[i] = (new_a, new_op)
            if all(s[1] == 1 for s in new_state):
                moves.append('win')
            else:
                moves.append(tuple(new_state))
        return moves

    memo = {}
    def is_winning(state):
        # state is a tuple of (a_i, op)
        if all(s[1] == 1 for s in state):
            return False  # shouldn't happen, but treat as losing for player to move
        if state in memo:
            return memo[state]
        moves = get_moves(state)
        for m in moves:
            if m == 'win':
