import sys

def mat_mult(A, B, mod):
    n = len(A)
    C = [[0]*n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            a = Ai[k]
            if a == 0:
                continue
            Bk = B[k]
            for j in range(n):
                Ci[j] = (Ci[j] + a * Bk[j]) % mod
    return C

def mat_pow(M, power, mod):
    n = len(M)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = M
    while power > 0:
        if power & 1:
            result = mat_mult(result, base, mod)
        base = mat_mult(base, base, mod)
        power >>= 1
    return result

