class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        # Convert string to list of ints for speed
        a = [int(c) for c in s]

        # Binary search on L (1 to n)
        lo, hi = 1, n
        ans = n

        def feasible(L: int) -> bool:
            # dp[c][len] = min flips to reach state where last char is c and current run of c has length len
            INF = float('inf')
            # Initialize for first character
            dp0 = [INF] * (L + 1)  # dp for last char = 0
            dp1 = [INF] * (L + 1)  # dp for last char = 1

            # First character
            orig = a[0]
            # Keep it
            if orig == 0:
                dp0[1] = 0
            else:
                dp1[1] = 0
            # Flip it
            flipped = 1 - orig
            if flipped == 0:
                dp1[1] = min(dp1[1], 1)
            else:
                dp0[1] = min(dp0[1], 1)

            # Process remaining characters
            for i in range(1, n):
                orig = a[i]
                new_dp0 = [INF] * (L + 1)
                new_dp1 = [INF] * (L + 1)

                for c, dp in [(0, dp0), (1, dp1)]:
                    for length in range(1, L + 1):
                        cost = dp[length]
                        if cost == INF:
                            continue
                        # Option 1: don't flip
                        new_c = orig
                        if new_c == c:
                            new_length = length + 1
                            if new_length <= L:
                                if c == 0:
                                    if cost < new_dp0[new_length]:
                                        new_dp0[new_length] = cost
                                else:
                                    if cost < new_dp1[new_length]:
                                        new_dp1[new_length] = cost
                        else:
                            new_length = 1
                            if new_c == 0:
                                if cost < new_dp0[new_length]:
                                    new_dp0[new_length] = cost
                            else:
                                if cost < new_dp1[new_length]:
                                    new_dp1[new_length] = cost

                        # Option 2: flip
                        new_c = 1 - orig
                        if new_c == c:
                            new_length = length + 1
                            if new_length <= L:
                                if c == 0:
                                    if cost + 1 < new_dp0[new_length]:
                                        new_dp0[new_length] = cost + 1
                                else:
                                    if cost + 1 < new_dp1[new_length]:
                                        new_dp1[new_length] = cost + 1
                        else:
                            new_length = 1
                            if new_c == 0:
                                if cost + 1 < new_dp0[new_length]:
                                    new_dp0[new_length] = cost + 1
                            else:
                                if cost + 1 < new_dp1[new_length]:
                                    new_dp1[new_length] = cost + 1

                dp0 = new_dp0
                dp1 = new_dp1

            # Find minimum cost in final states
            min_cost = INF
            for length in range(1, L + 1):
                if dp0[length] < min_cost:
                    min_cost = dp0[length]
                if dp1[length] < min_cost:
                    min_cost = dp1[length]
            return min_cost <= numOps

        # Binary search for smallest L
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1

        return ans

class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        counts = [0] * 26
        for c in s:
            counts[ord(c) - ord('a')] += 1
        sorted_counts = sorted(counts, reverse=True)
        ans = n  # cost of deleting all characters
        for k in range(1, n + 1):
            excess = 0
            deficit = 0
            unkept = n
            # incrementally evaluate keeping d = 1, 2, ..., 26 distinct chars
            for d in range(26):
                c = sorted_counts[d]
                unkept -= c
                if c > k:
                    excess += c - k
                else:
                    deficit += k - c
                # cost for keeping the top d+1 characters
                cost = excess + max(unkept, deficit)
                if cost < ans:
                    ans = cost
        return ans

from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        self.count -= 1
        return True

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        # Map value to index for O(1) lookup
        pos = {v: i for i, v in enumerate(nums)}
        uf = UnionFind(n)

        # For each element, find multiples in array that are <= threshold
        for i, a in enumerate(nums):
            if a > threshold:
                # No edges possible for this element (isolated)
                continue
            # Iterate multiples of a: a, 2a, 3a, ... up to threshold
            m = a
            while m <= threshold:
                if m in pos and pos[m] != i:
                    uf.union(i, pos[m])
                m += a
                # Avoid infinite loop if a == 0 (not possible per constraints)
                if a == 0:
                    break

        return uf.count
